const canvas=document.getElementById('game'),c=canvas.getContext('2d'),overlay=document.getElementById('overlay'),title=document.getElementById('title'),tag=document.getElementById('tag'),desc=document.getElementById('desc'),start=document.getElementById('start'),mode=document.getElementById('mode');
const W=1280,H=680,G=565,keys={},pressed={};let state='menu',two=false,players=[],timer=99,frame=0,round=1,roundDelay=0,announcement='',announceTime=0,particles=[],projectiles=[],shake=0,paused=false,last=0,acc=0;
function fighter(x,id){return {x,y:G,vx:0,vy:0,id,health:100,meter:0,wins:0,attack:null,stun:0,flash:0,facing:id===1?1:-1,crouch:false,guard:false,ai:0};}
function resetMatch(){players=[fighter(345,1),fighter(935,2)];round=1;resetRound();state='fight';overlay.classList.add('hidden');paused=false}
function resetRound(){let [a,b]=players;a.x=345;b.x=935;for(let p of players){p.y=G;p.vx=p.vy=0;p.health=100;p.attack=null;p.stun=0;p.guard=false;p.crouch=false}timer=99;projectiles=[];roundDelay=0;announcement='ROUND '+round;announceTime=110}
function endRound(){if(roundDelay)return;let a=players[0],b=players[1];if(a.health>b.health)a.wins++;else if(b.health>a.health)b.wins++;roundDelay=200;announcement=a.health===b.health?'DRAW':(a.health>b.health?'KAI':'VEX')+' WINS';announceTime=160}
function endMatch(){let win=players[0].wins>players[1].wins;state='menu';tag.textContent='●   MATCH COMPLETE';title.innerHTML=win?'VICTORY<br><span>IS YOURS.</span>':'THE NIGHT<br><span>FIGHTS BACK.</span>';desc.textContent=win?'The city knows your name. Ready to defend it?':'Every loss is a lesson. Step back into the ring.';start.textContent='Fight again ↗';overlay.classList.remove('hidden')}
function act(p,type){if(p.attack||p.stun||roundDelay)return;let data=type==='punch'?{duration:23,hit:8,damage:7,reach:115}:type==='kick'?{duration:33,hit:13,damage:11,reach:155}:{duration:45,hit:18,damage:13,reach:0};if(type==='special'){if(p.meter<50)return;p.meter-=50}p.attack={type,t:0,...data,done:false}}
function burst(x,y,color,n=12){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*12,vy:(Math.random()-.5)*12,life:15+Math.random()*14,color})}
function hit(att,def,damage,dir){if(def.stun>5)return;let blocked=def.guard&&def.y===G;def.health=Math.max(0,def.health-(blocked?damage*.18:damage));def.stun=blocked?9:20;def.vx=dir*(blocked?3:8);def.flash=8;att.meter=Math.min(100,att.meter+(blocked?4:12));def.meter=Math.min(100,def.meter+5);shake=blocked?3:9;burst(def.x,def.y-115,blocked?'#a7e7ff':'#f8e782');}
function control(p,other){if(p.stun||roundDelay)return;let left,right,up,down,punch,kick,special;if(p.id===1){left=keys.a;right=keys.d;up=pressed.w;down=keys.s;punch=pressed.j;kick=pressed.k;special=pressed.l}else if(two){left=keys.arrowleft;right=keys.arrowright;up=pressed.arrowup;down=keys.arrowdown;punch=pressed['1'];kick=pressed['2'];special=pressed['3']}else{p.ai--;let distance=Math.abs(p.x-other.x);if(p.ai<=0){p.ai=14+Math.random()*24;p.intent=Math.random()}left=distance>130&&p.x>other.x;right=distance>130&&p.x<other.x;down=p.intent<.08;up=p.intent>.95&&distance<230;punch=distance<120&&p.intent<.3;kick=distance<160&&p.intent>.65;special=p.meter>=50&&distance>180&&p.intent>.8; if(p.intent<.12&&distance<200){left=p.x<other.x;right=p.x>other.x}}
 p.crouch=!!down&&p.y===G;p.guard=!!((p.facing===1&&left)||(p.facing===-1&&right))&&p.y===G&&!p.attack;p.vx=p.attack||p.crouch?0:(right?4.2:0)-(left?4.2:0);if(up&&p.y===G){p.vy=-17;p.guard=false}if(punch)act(p,'punch');else if(kick)act(p,'kick');else if(special)act(p,'special')}
function update(){frame++;if(state!=='fight'||paused)return;let [a,b]=players;if(announceTime>0)announceTime--;if(roundDelay){roundDelay--;if(roundDelay===0){if(a.wins>=2||b.wins>=2)endMatch();else{round++;resetRound()}}}else{timer=Math.max(0,timer-1/60);if(timer===0||a.health<=0||b.health<=0)endRound()}
 a.facing=a.x<b.x?1:-1;b.facing=-a.facing;control(a,b);control(b,a);for(let p of players){if(p.stun>0)p.stun--;if(p.flash>0)p.flash--;p.x=Math.max(60,Math.min(W-60,p.x+p.vx));p.y+=p.vy;p.vy+=.78;if(p.y>=G){p.y=G;p.vy=0}if(p.stun)p.vx*=.84;if(p.attack){let t=++p.attack.t,atk=p.attack,other=p===a?b:a;if(t===atk.hit&&!atk.done){atk.done=true;if(atk.type==='special'){projectiles.push({x:p.x+p.facing*55,y:p.y-115,dir:p.facing,owner:p,life:100})}else if(Math.abs(p.x-other.x)<atk.reach&&Math.abs(p.y-other.y)<110&&Math.sign(other.x-p.x)===p.facing)hit(p,other,atk.damage,p.facing)}if(t>atk.duration)p.attack=null}}
 if(Math.abs(a.x-b.x)<62){let push=(62-Math.abs(a.x-b.x))/2;a.x-=a.facing*push;b.x+=a.facing*push}for(let p of projectiles){p.x+=p.dir*10;p.life--;let other=p.owner===a?b:a;if(Math.abs(p.x-other.x)<48&&Math.abs(p.y-(other.y-115))<80){hit(p.owner,other,13,p.dir);p.life=0;burst(p.x,p.y,'#a4faff')} }projectiles=projectiles.filter(p=>p.life>0&&p.x>0&&p.x<W);for(let p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.25;p.life--}particles=particles.filter(p=>p.life>0);if(shake>0)shake*=.8;for(let k in pressed)delete pressed[k]}
function rect(x,y,w,h,color){c.fillStyle=color;c.fillRect(x,y,w,h)}function line(x,y,x2,y2,color,width=1){c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.moveTo(x,y);c.lineTo(x2,y2);c.stroke()}function text(t,x,y,size,color,align='left',font='Barlow Condensed'){c.fillStyle=color;c.textAlign=align;c.font=`900 ${size}px '${font}'`;c.fillText(t,x,y)}
function stage(){let sky=c.createLinearGradient(0,0,0,565);sky.addColorStop(0,'#121e30');sky.addColorStop(.55,'#3c4d57');sky.addColorStop(1,'#b67a64');rect(0,0,W,565,sky);c.fillStyle='#e9b393';c.beginPath();c.arc(1000,165,75,0,7);c.fill();for(let i=0;i<22;i++){let x=i*67-20,h=100+(i*71%180);rect(x,410-h,55,h,'#273641');for(let j=0;j<4;j++)for(let k=0;k<4;k++)if((i+j+k)%3===0)rect(x+8+j*11,420-h+k*24,5,9,'#d7a975')}
 rect(0,340,310,225,'#1b292e');rect(0,335,310,12,'#0e191d');rect(35,371,170,110,'#6d3b35');rect(43,380,154,93,'#d9885f');for(let i=0;i<6;i++)rect(48+i*24,383,13,84,i%2?'#ac5946':'#eab27b');rect(249,340,22,225,'#162329');rect(270,250,90,115,'#342e35');rect(280,260,70,95,'#c54946');text('夜',315,300,34,'#f7cb78','center');text('市',315,340,34,'#f7cb78','center');rect(911,318,369,247,'#27343a');rect(940,350,283,130,'#162a30');for(let i=0;i<5;i++){rect(951+i*53,362,42,103,'#b96b54');rect(956+i*53,367,32,93,'#e6ae77')}rect(1005,256,190,58,'#e9c56e');text('NIGHT MARKET',1100,295,27,'#253a38','center');line(0,242,1280,180,'#141f23',4);for(let i=0;i<13;i++){let x=i*108+20,y=240-i*5;line(x,y,x,y+25,'#18252a',2);c.fillStyle=i%2?'#f3bb70':'#ef7a63';c.beginPath();c.ellipse(x,y+31,11,14,0,0,7);c.fill()}
 rect(0,565,1280,115,'#352e30');rect(0,565,1280,8,'#d5a171');for(let i=0;i<12;i++)line(i*130,573,i*155-100,680,'#5e4944',2);for(let y=600;y<680;y+=35)line(0,y,1280,y,'#5b4440',2);rect(0,0,W,H,'#121c1b18')}
function limb(x1,y1,x2,y2,width,color){c.lineCap='round';line(x1,y1,x2,y2,'#192024',width+8);line(x1,y1,x2,y2,color,width)}
function drawFighter(p){let x=p.x,y=p.y,bob=p.y===G?Math.sin(frame*.12+p.id)*2:0,f=p.facing,atk=p.attack,active=atk&&atk.t>atk.hit-6&&atk.t<atk.hit+8, crouch=p.crouch?30:0; c.save();c.translate(x,y);c.scale(f,1);c.translate(0,bob);c.fillStyle='#151f20aa';c.beginPath();c.ellipse(0,4,56,10,0,0,7);c.fill();let skin=p.id===1?'#cf9169':'#d8a48b',shirt=p.id===1?'#dce6bf':'#d75058',pants=p.id===1?'#315d69':'#283b4d',accent=p.id===1?'#d8ff48':'#ffb068';let lean=atk?10:0;let hip=-82+crouch,shoulder=-160+crouch,head=-200+crouch;
 limb(-18,hip,-30,-42+crouch*.5,24,pants);limb(-30,-42+crouch*.5,-37,-8,19,pants);limb(18,hip,active&&atk.type==='kick'?65:25,active&&atk.type==='kick'?-100:-43+crouch*.5,25,pants);limb(active&&atk.type==='kick'?65:25,active&&atk.type==='kick'?-100:-43+crouch*.5,active&&atk.type==='kick'?125:38,active&&atk.type==='kick'?-105:-8,18,pants);limb(-40,-8,-22,-6,15,'#e2d6b5');if(!(active&&atk.type==='kick'))limb(34,-8,50,-6,15,'#e2d6b5');c.fillStyle='#192024';c.beginPath();c.moveTo(-35,shoulder);c.lineTo(28,shoulder-5);c.lineTo(36,hip+7);c.lineTo(-33,hip+5);c.closePath();c.fill();c.fillStyle=shirt;c.beginPath();c.moveTo(-27,shoulder+4);c.lineTo(23,shoulder);c.lineTo(27,hip);c.lineTo(-25,hip);c.closePath();c.fill();rect(-30,hip-6,60,12,accent);limb(-26,shoulder+18,-46,shoulder+45,19,skin);limb(-46,shoulder+45,-10,shoulder+54,17,skin);limb(25,shoulder+15,active&&atk.type==='punch'?72:44,active&&atk.type==='punch'?shoulder+22:shoulder+40,20,skin);limb(active&&atk.type==='punch'?72:44,active&&atk.type==='punch'?shoulder+22:shoulder+40,active&&atk.type==='punch'?112:29,active&&atk.type==='punch'?shoulder+18:shoulder+55,17,skin);c.fillStyle=skin;c.beginPath();c.arc(0,head+8,29,0,7);c.fill();c.fillStyle='#1b2025';c.beginPath();c.arc(-4,head,29,Math.PI,Math.PI*2);c.lineTo(24,head+4);c.lineTo(-25,head+6);c.fill();rect(-30,head+2,60,7,accent);rect(12,head+12,8,3,'#181c20');if(p.flash)rect(-40,head-22,80,140,'#ffffff66');c.restore()}
function hud(){let [a,b]=players;if(!a)return;rect(35,27,490,24,'#141c22');rect(755,27,490,24,'#141c22');rect(40,32,480*a.health/100,14,'#dcff63');rect(1240-480*b.health/100,32,480*b.health/100,14,'#f1806f');text('KAI',40,83,29,'#fff');text('VEX',1240,83,29,'#fff','right');text('PLAYER 01',41,100,11,'#d6ddcf','left','Space Mono');text(two?'PLAYER 02':'CPU',1239,100,11,'#d6ddcf','right','Space Mono');rect(35,625,300,12,'#19232b');rect(945,625,300,12,'#19232b');rect(39,628,292*a.meter/100,6,'#95eaf1');rect(1241-292*b.meter/100,628,292*b.meter/100,6,'#95eaf1');text('SUPER',36,618,11,'#d3ebea','left','Space Mono');text('SUPER',1244,618,11,'#d3ebea','right','Space Mono');text(String(Math.ceil(timer)).padStart(2,'0'),640,70,52,'#f5f2d6','center');for(let i=0;i<2;i++){rect(42+i*18,108,12,7,i<a.wins?'#d8ff48':'#626a60');rect(1226-i*18,108,12,7,i<b.wins?'#ff9e82':'#626a60')}if(announceTime>0){text(announcement,640,310,70,'#141a1b','center');text(announcement,636,305,70,'#f5f1d5','center')}if(paused)text('PAUSED',640,350,74,'#d8ff48','center')}
function render(){c.save();if(shake>.5)c.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);stage();if(players.length){players.forEach(drawFighter);for(let p of projectiles){c.fillStyle='#a5fcff';c.beginPath();c.arc(p.x,p.y,22,0,7);c.fill();c.strokeStyle='#e8ffff';c.lineWidth=5;c.stroke()}for(let p of particles){c.globalAlpha=Math.max(0,p.life/30);rect(p.x,p.y,6,6,p.color)}c.globalAlpha=1;hud()}else{drawFighter({x:830,y:G,id:1,facing:1,crouch:false});drawFighter({x:1070,y:G,id:2,facing:-1,crouch:false})}c.restore()}
function loop(t){if(!last)last=t;acc+=Math.min(100,t-last);last=t;while(acc>=1000/60){update();acc-=1000/60}render();requestAnimationFrame(loop)}requestAnimationFrame(loop);
start.onclick=resetMatch;mode.onclick=()=>{two=!two;mode.textContent=two?'LOCAL 2P':'VS CPU'};window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!keys[k])pressed[k]=true;keys[k]=true;if(k==='p'&&!e.repeat&&state==='fight')paused=!paused});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{for(let k in keys)keys[k]=false;if(state==='fight')paused=true});document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(!keys[k])pressed[k]=true;keys[k]=true});b.addEventListener('pointerup',()=>keys[k]=false);b.addEventListener('pointercancel',()=>keys[k]=false)});
